<script setup lang="ts">
import {ref,computed,watch,onUnmounted} from 'vue'
import {useRouter} from 'vue-router'
import {useWorkspace} from '../store'
import {api,fmt} from '../api'
import Icon from '../components/Icon.vue'
import Status from '../components/Status.vue'
const store=useWorkspace(),router=useRouter(),data=ref<any>(null),loading=ref(false)
let version=0
async function load(){if(!store.projectId)return;const v=++version;loading.value=!data.value;try{const res=await api.get(`projects/${store.projectId}/overview/`);if(v===version)data.value=res.data}finally{loading.value=false}}
watch(()=>store.projectId,()=>{data.value=null;load()},{immediate:true})
const timer=setInterval(()=>{if(data.value?.active_runs)load()},3000);onUnmounted(()=>clearInterval(timer))
const stats=computed(()=>[{label:'UI 用例',value:data.value?.cases??0,unit:'条',icon:'Tickets',color:'violet',note:'沉淀可复用的测试资产',path:'/ui-testing'},{label:'测试计划',value:data.value?.plans??0,unit:'个',icon:'Calendar',color:'blue',note:'有序组织每一次测试',path:'/assets/plan'},{label:'累计执行',value:data.value?.runs??0,unit:'次',icon:'VideoPlay',color:'orange',note:`${data.value?.active_runs??0} 个任务进行中 · 模拟模式`,path:'/runs'},{label:'用例通过率',value:data.value?.pass_rate??0,unit:'%',icon:'CircleCheck',color:'green',note:`基于 ${data.value?.tested_cases??0} 次模拟用例结果`,path:'/runs'}])
const max=computed(()=>Math.max(4,...(data.value?.trend||[]).map((d:any)=>d.total)))
const points=computed(()=>(data.value?.trend||[]).map((d:any,i:number)=>`${40+i*83},${154-d.total/max.value*114}`).join(' '))
const passPoints=computed(()=>(data.value?.trend||[]).map((d:any,i:number)=>`${40+i*83},${154-d.passed/max.value*114}`).join(' '))
const quick=[{icon:'DocumentAdd',title:'编写 UI 用例',desc:'按 App / Web 组织自动化用例',path:'/ui-testing',color:'violet'},{icon:'Calendar',title:'组织测试计划',desc:'选择用例，准备一次测试',path:'/assets/plan',color:'blue'},{icon:'Cpu',title:'配置智能 Agent',desc:'编排模型与工具能力',path:'/resources/agent',color:'orange'},{icon:'DataAnalysis',title:'查看测试报告',desc:'追踪结果，定位测试问题',path:'/runs',color:'green'}]
</script>
<template><div class="dashboard" v-loading="loading">
 <div class="page-heading"><div><div class="heading-eyebrow">WORKSPACE OVERVIEW</div><h1>{{ $t('工作台') }}<span class="heading-tag">{{store.project?.key}}</span></h1><p>你好，{{store.user.username}}。一切就绪，开始今天的测试工作。</p></div><el-button type="primary" @click="router.push('/assets/plan')"><Icon name="Plus"/>{{ $t('新建测试计划') }}</el-button></div>
 <div class="welcome-banner"><div class="banner-copy"><span class="banner-kicker"><i></i> AI-POWERED TESTING</span><h2>{{ $t('连接智能能力，构建高效测试闭环') }}</h2><p>{{ $t('从测试设计到执行分析，让模型、工具与团队协同工作。') }}</p><el-button @click="router.push('/resources/agent')">{{ $t('探索智能 Agent') }}<Icon name="Right" :size="15"/></el-button></div><div class="banner-art"><div class="art-grid"></div><div class="art-line one"></div><div class="art-line two"></div><div class="art-tile art-model"><Icon name="Connection" :size="24"/><span>{{ $t('模型') }}</span></div><div class="art-tile art-core"><Icon name="Cpu" :size="34"/><span>Agent</span><i>✦</i></div><div class="art-tile art-skill"><Icon name="MagicStick" :size="23"/><span>Skill</span></div><div class="art-tile art-mcp"><Icon name="Link" :size="23"/><span>MCP</span></div><span class="spark spark-one">✦</span><span class="spark spark-two">+</span></div></div>
 <div class="stats-grid"><button v-for="s in stats" :key="s.label" class="stat-card" @click="router.push(s.path)"><div class="stat-top"><span>{{s.label}}</span><span class="icon-box" :class="s.color"><Icon :name="s.icon"/></span></div><div class="stat-value">{{s.value}}<small>{{s.unit}}</small></div><div class="stat-note"><span v-if="s.color==='green'" class="online-dot"></span>{{s.note}}<Icon name="Right" :size="13"/></div></button></div>
 <section class="panel quick-panel"><div class="panel-heading"><h3>{{ $t('快捷开始') }}</h3><span>{{ $t('让下一步，更简单') }}</span></div><div class="quick-grid"><button v-for="q in quick" :key="q.title" @click="router.push(q.path)"><span class="quick-icon" :class="q.color"><Icon :name="q.icon" :size="23"/></span><div><strong>{{q.title}}</strong><small>{{q.desc}}</small></div><Icon name="ArrowRight" :size="13"/></button></div></section>
 <div class="analytics-grid"><section class="panel trend-panel"><div class="panel-heading"><h3>{{ $t('测试执行趋势') }}<span class="mini-badge">{{ $t('模拟') }}</span></h3><span class="period">{{ $t('最近 7 天') }}<Icon name="ArrowDown" :size="11"/></span></div><div class="chart-legend"><span><i class="legend-purple"></i>{{ $t('执行用例') }}</span><span><i class="legend-green"></i>{{ $t('通过用例') }}</span></div><svg class="trend-chart" viewBox="0 0 580 196" role="img" aria-label="最近七天模拟用例执行与通过数量"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#7279ef" stop-opacity=".16"/><stop offset="1" stop-color="#7279ef" stop-opacity="0"/></linearGradient></defs><g v-for="n in 4" :key="n"><line x1="40" x2="538" :y1="154-(n-1)*38" :y2="154-(n-1)*38" stroke="#edf0f5" stroke-dasharray="4 4"/><text x="24" :y="158-(n-1)*38" text-anchor="end">{{Math.round((n-1)*max/3)}}</text></g><polygon :points="`40,154 ${points} 538,154`" fill="url(#area)"/><polyline :points="points" fill="none" stroke="#7779eb" stroke-width="2.5"/><polyline :points="passPoints" fill="none" stroke="#5ec8ac" stroke-width="2.5"/><g v-for="(d,i) in data?.trend||[]" :key="d.date"><circle :cx="40+Number(i)*83" :cy="154-d.total/max*114" r="3" fill="white" stroke="#7779eb" stroke-width="2"/><text :x="40+Number(i)*83" y="183" text-anchor="middle">{{d.date.slice(5).replace('-','/')}}</text></g></svg></section>
 <section class="panel health-panel"><div class="panel-heading"><h3>{{ $t('项目资源概览') }}</h3><router-link to="/projects">{{ $t('管理') }}<Icon name="ArrowRight" :size="11"/></router-link></div><div class="resource-summary"><div class="resource-ring"><Icon name="FolderOpened" :size="30"/></div><div><strong>{{store.project?.name}}</strong><p>{{data?.resources??0}} 项智能资源已配置</p><span class="mode-pill">{{ $t('模拟模式') }}</span></div></div><div class="asset-totals"><div v-for="(label,kind) in {document:'测试文档',case:'UI 用例',flow:'测试流程'}" :key="kind"><span>{{label}}</span><b>{{kind==='case'?(data?.cases??0):(data?.assets_by_kind.find((x:any)=>x.kind===kind)?.count??0)}}</b></div></div><div class="health-note"><Icon name="InfoFilled" :size="14"/>{{ $t('尚未连接真实 AI、MCP 或设备服务') }}</div></section></div>
 <section class="panel recent-panel"><div class="panel-heading"><h3>{{ $t('最近测试执行') }}<span class="count-badge">{{data?.runs??0}}</span></h3><router-link to="/runs">{{ $t('查看全部') }}<Icon name="ArrowRight" :size="12"/></router-link></div><el-table :data="data?.recent_runs||[]" @row-click="(r:any)=>router.push('/runs/'+r.id)" class="clickable-table"><el-table-column :label="$t('测试任务')" min-width="240"><template #default="{row}"><div class="table-title"><span class="table-icon"><Icon name="DocumentChecked" :size="17"/></span><div><strong>{{row.name}}</strong><small>RUN-{{String(row.id).padStart(4,'0')}} · 模拟执行</small></div></div></template></el-table-column><el-table-column :label="$t('执行状态')" width="120"><template #default="{row}"><Status :value="row.status"/></template></el-table-column><el-table-column :label="$t('通过 / 总数')" width="120"><template #default="{row}"><span class="muted"><b class="text-green">{{row.metrics.passed??'—'}}</b> / {{row.metrics.total??'—'}}</span></template></el-table-column><el-table-column :label="$t('通过率')" width="150"><template #default="{row}"><el-progress v-if="row.status==='completed'" :percentage="row.metrics.pass_rate" :stroke-width="5" color="#67c6a5"/><span v-else class="muted">—</span></template></el-table-column><el-table-column :label="$t('执行时间')" width="150"><template #default="{row}">{{fmt(row.created_at)}}</template></el-table-column><el-table-column :label="$t('操作')" width="75"><template #default="{row}"><el-button link type="primary" @click.stop="router.push('/runs/'+row.id)">{{ $t('详情') }}</el-button></template></el-table-column><template #empty><el-empty :description="$t('还没有执行记录，创建测试计划后开始第一次测试')" :image-size="60"/></template></el-table></section>
</div></template>
